    let d = g.r;
    let r = max(min(t * tanH, t * planeC + 0.35 * h), 0.25 * h);
    // rc is the coverage radius. Treating every axis crossing as a full hit dilates
    // silhouettes by about rc / 4, so rc is a fraction (G.rc.z) of the cone radius.
    let rc = r * G.rc.z;
